mapper.select:
select * from (SELECT REVEAL.ID id ,REVEAL.REP_ID repId ,REVEAL.REPORT_NAME reportName ,REVEAL.PROD_NAME prodName ,REVEAL.PRODID prodid ,case when REVEAL.START_DATE is null or REVEAL.START_DATE = REVEAL.END_DATE then DATE_FORMAT(REVEAL.END_DATE,'%Y-%m-%d') else CONCAT_WS( '',DATE_FORMAT(REVEAL.START_DATE,'%Y-%m-%d') , '--',DATE_FORMAT(REVEAL.END_DATE,'%Y-%m-%d')) end reportDate ,REVEAL.END_DATE endDate ,REVEAL.START_DATE startDate ,REVEAL.SYS_FILENAME sysFilename ,REVEAL.SYS_FILEPATH sysFilepath ,REVEAL.REVEAL_DATE revealDate ,REVEAL.FILEPATH filepath ,REVEAL.FILENAME filename ,REVEAL.CONFIRM_STATUS confirmStatus ,REVEAL.REVEAL_STATUS revealStatus ,REVEAL.STATUS status ,REVEAL.CREATE_USER createUser ,REVEAL.CREATE_DEPT createDept ,REVEAL.CREATE_TIME createTime ,REVEAL.UPDATE_USER updateUser ,REVEAL.UPDATE_TIME updateTime ,DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') createTimeStr ,DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') confirmDateStr ,REVEAL.SYS_FILEPATH seqno ,REVEAL.REVEAL_CHANNEL revealChannel ,REVEAL.IS_CONFIRM isConfirm ,REVEAL.IS_REVEAL isReveal ,REVEAL.DETAIL detail ,DATE_FORMAT(REVEAL.TIME,'%Y-%m-%d') uploadTime ,REVEAL.CONFIRM_USER confirmUser ,REVEAL.REPORT_CATEGORY reportCategory ,rfp.NAME reportCategoryName ,DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d %h:%i:%s') revealEndDateStr ,REVEAL.ANNEX annex ,REVEAL.ANNEX_PATH annexPath FROM REP_REVEAL REVEAL left join rep_info info on REVEAL.rep_id = info.rep_id left join rep_ftp_path rfp on REVEAL.REPORT_CATEGORY = rfp.ID where 1=1 and REVEAL.status ='E'
AND (case when REVEAL.REVEAL_STATUS = null then '02' else REVEAL.REVEAL_STATUS end ) = #{revealStatus,jdbcType=VARCHAR}
AND REVEAL.PRODID IN
#{item}
AND REVEAL.REPORT_NAME like CONCAT_WS(CONCAT_WS('%',#{reportName,jdbcType=VARCHAR}),'%')
AND DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') >= #{valDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CREATE_TIME,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}
AND (case when REVEAL.CONFIRM_STATUS = null then '02' else REVEAL.CONFIRM_STATUS end ) = #{confirmStatus,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') >= #{confirmDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.CONFIRM_DATE,'%Y-%m-%d') <= #{confirmDateEnd,jdbcType=VARCHAR}
AND REVEAL.IS_CONFIRM IN
#{item}
AND (
REVEAL.REVEAL_CHANNEL like CONCAT_WS(CONCAT_WS('%',#{item}),'%')
)
AND DATE_FORMAT(REVEAL.REVEAL_DATE,'%Y-%m-%d') >= #{revealDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_DATE,'%Y-%m-%d') <= #{revealDateEnd,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(REVEAL.REVEAL_END_DATE,'%Y-%m-%d') <= #{revealEndDateEnd,jdbcType=VARCHAR}
AND REVEAL.REPORT_CATEGORY IN
#{item}
order by REVEAL.CONFIRM_STATUS DESC,
REVEAL.REVEAL_STATUS DESC,
REVEAL.CREATE_TIME DESC) TEMPAA where 1=1

select prd.finprod_id,IFNULL(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd 
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}

 SELECT 
		CONCAT_WS( '',r.PROD_NAME,'_',rfp.NAME)  as SYS_FILENAME
 FROM REP_REVEAL r 
 left join  rep_ftp_path  rfp
 ON  r.REPORT_CATEGORY = rfp.ID
 WHERE r.SYS_FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
 or  r.FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
 or  r.ANNEX_PATH=#{sysFilepath, jdbcType=VARCHAR}

mapper.update:
      update REP_REVEAL
      set 
      FILEPATH = #{filepath,jdbcType=VARCHAR}
      ,FILENAME = #{filename,jdbcType=VARCHAR}
      ,TIME = #{time,jdbcType=TIMESTAMP}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      ANNEX_PATH = #{annexPath,jdbcType=VARCHAR}
      ,ANNEX = #{annex,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      CONFIRM_STATUS = #{confirmStatus,jdbcType=VARCHAR},
      CONFIRM_DATE = #{confirmDate,jdbcType=DATE},
      CONFIRM_USER = #{confirmUser,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}


	  	,IS_CONFIRM=#{isConfirm,jdbcType=VARCHAR}

      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      REVEAL_STATUS = #{revealStatus,jdbcType=VARCHAR},
      REVEAL_DATE = #{revealDate,jdbcType=DATE},
      REVEAL_USER = #{revealUser,jdbcType=VARCHAR}

	  	,IS_REVEAL=#{isReveal,jdbcType=VARCHAR}

      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      STATUS = #{status,jdbcType=VARCHAR}
      ,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and id = #{id,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set confirm_Status=#{confirmStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

      update BOK_VALBAL_TABLE_STATUS a
      set NOTICE_STATUS=#{noticeStatusCode,jdbcType=VARCHAR}
      where 1=1

		and a.finprod_Id=#{finprodId,jdbcType=VARCHAR}


		and a.val_Date=STR_TO_DATE(#{valDate,jdbcType=VARCHAR},'%Y-%m-%d')


		and a.val_Bal_Flag=#{valBalFlagCode,jdbcType=VARCHAR}

update REP_REVEAL rr

	set rr.FILEPATH = null, rr.TIME = null, rr.FILENAME = null


	set rr.ANNEX = null, rr.ANNEX_PATH = null

,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}
,UPDATE_TIME = NOW()
where rr.ID = #{id, jdbcType=VARCHAR}

      update REP_REVEAL
      set 
      FILEPATH = #{filepath,jdbcType=VARCHAR}
      ,FILENAME = #{filename,jdbcType=VARCHAR}
      ,TIME = #{time,jdbcType=DATE}
	  ,UPDATE_TIME = NOW()
      where 1=1
      and STATUS = 'E'

      and REPORT_NAME = #{reportName,jdbcType=VARCHAR}


      and PRODID = #{prodid,jdbcType=VARCHAR}


      and ( START_DATE = #{startDate,jdbcType=DATE}


		or END_DATE= #{startDate,jdbcType=DATE} )

mapper.select:
select count(0)
from BOK_FILE_TRANSFER bft
where bft.FINPROD_ID = #{finprodId}
  and bft.VAL_BAL_FLAG = #{valBalFlag}
  and bft.VAL_DATE = #{valDate}
  and bft.FILE_NAME = #{fileName}

mapper.delete:
        delete from BOK_FILE_TRANSFER bft
       where bft.FINPROD_ID = #{finprodId}
	     and bft.VAL_BAL_FLAG = #{valBalFlag}
	     and bft.VAL_DATE = #{valDate}
	     and bft.FILE_NAME = #{fileName}

mapper.select:
   select bncf.file_id,
       bncf.finprod_id,
       bncf.val_bal_flag,
       bncf.val_date,
       bfi.file_name
  from BOK_NETVALUE_CFM_FILE bncf
  left join BOK_FILE_INFO bfi
  on bncf.file_id = bfi.file_id
  where bncf.finprod_id = #{finprodId}
	and bncf.val_bal_flag = #{valBalFlag}
	and bncf.val_date = #{valDate}
	and bfi.file_name = #{fileName}

   select bfi.FILE_ID from
	  BOK_FILE_INFO  bfi
	where bfi.file_type = #{fileType}
      and bfi.file_name = #{fileName}
      and bfi.file_path = #{filePath}

SELECT rr.ID id, rr.REP_ID repId, rr.PROD_NAME prodName, rr.PRODID prodid, rr.END_DATE endDate, rr.START_DATE startDate, rr.SYS_FILENAME sysFilename, rr.SYS_FILEPATH sysFilepath, rr.FILEPATH filepath, rr.FILENAME filename, rr.CONFIRM_STATUS confirmStatus, rr.REVEAL_STATUS revealStatus, rr.REVEAL_DATE revealDate, rr.CONFIRM_DATE confirmDate, rr.REPORT_NAME reportName, rr.REPORT_CATEGORY reportCategory FROM REP_REVEAL rr WHERE rr.STATUS = 'E'
AND rr.ID in
#{item}

	SELECT case when r.SYS_FILEPATH=#{sysFilepath, jdbcType=VARCHAR} then SYS_FILENAME
	when r.FILEPATH =#{sysFilepath, jdbcType=VARCHAR} then FILENAME
	when r.ANNEX_PATH=#{sysFilepath, jdbcType=VARCHAR} then ANNEX else null end as SYS_FILENAME FROM REP_REVEAL r
    WHERE
    	r.SYS_FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
    or  r.FILEPATH=#{sysFilepath, jdbcType=VARCHAR}
    or  r.ANNEX_PATH=#{sysFilepath, jdbcType=VARCHAR}

SELECT  COUNT(1)
FROM	REP_REVEAL
WHERE
1=1

	AND PRODID = #{prodid,jdbcType=VARCHAR}


	AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


	and ( START_DATE = #{startDate,jdbcType=DATE}


	OR END_DATE = #{startDate,jdbcType=DATE} )

AND STATUS='E'
AND CONFIRM_STATUS='01'
